let ticking=false;function update(){ticking=false;let r=$('#layers').getBoundingClientRect(),p=Math.max(0,Math.min(1,-r.top/(r.height-innerHeight)));if(!manual){setSpread(reduced.matches?1:p);let i=Math.min(5,Math.floor(p*6));if(i!==selected)select(i)}if(!reduced.matches){$('.hero>img').style.transform=`translateY(${Math.min(scrollY*.22,innerHeight*.4)}px)`;$('.hero-copy').style.transform=`translateY(${Math.min(scrollY*.10,100)}px)`}}
addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(update);ticking=true}},{passive:true});addEventListener('resize',update);reduced.addEventListener('change',update);document.documentElement.classList.add('js');new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.15}).observe($('.intro h2'));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.1});document.querySelectorAll('.reveal').forEach(e=>io.observe(e));select(0);update();
// New original instrumental: warm electric-piano voicings, soft bass and sparse arpeggio, 72 BPM.
let ctx,master,timer,on=false,step=0;
const chords=[[48,55,59,62,67],[45,52,55,59,64],[41,48,52,55,60],[43,50,53,57,62]];
function tone(midi,t,dur,volume,bass=false){const f=440*2**((midi-69)/12);for(let h=1;h<=3;h++){const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=f*h;g.gain.setValueAtTime(.00001,t);g.gain.exponentialRampToValueAtTime(volume/(h*h*h),t+.035);g.gain.exponentialRampToValueAtTime(.00001,t+dur);o.connect(g);g.connect(master);o.start(t);o.stop(t+dur+.05)}}
function phrase(){if(!on)return;const t=ctx.currentTime,c=chords[Math.floor(step/8)%4];if(step%8===0){c.forEach((n,j)=>tone(n,t+j*.035,3.1,.08));tone(c[0]-12,t,2.7,.11,true)}if(step%2===0)tone(c[[2,4,3,1][Math.floor(step/2)%4]]+12,t+.08,1.7,.065);step++}
async function toggleMusic(){try{if(!ctx){ctx=new(window.AudioContext||window.webkitAudioContext)();master=ctx.createGain();master.gain.value=.65;const compressor=ctx.createDynamicsCompressor();master.connect(compressor);compressor.connect(ctx.destination)}if(on){on=false;clearInterval(timer);await ctx.suspend()}else{await ctx.resume();on=true;phrase();timer=setInterval(phrase,60000/72/2)}$('#music').setAttribute('aria-pressed',String(on));$('#music span').textContent=on?'Music on':'Music off'}catch(e){$('#music span').textContent='Tap to retry';on=false;clearInterval(timer)}}$('#music').onclick=toggleMusic;document.addEventListener('visibilitychange',()=>{if(document.hidden&&on)toggleMusic()});
